export const agentHook = "#!/usr/bin/env bash\n# Agent Stop hook: report new Rogen diagnostics about changed files before the agent ends its turn.\n# Pass \"cursor\" as the first argument for Cursor, which replies with followup_message.\npayload=$(cat)\nsession=$(jq -r '.session_id // .sessionId // .conversation_id // \"agent\"' <<<\"$payload\")\ncd \"${CLAUDE_PROJECT_DIR:-$(jq -r '.cwd // \".\"' <<<\"$payload\")}\" || exit 0\ncompgen -G '*.rogen.json' >/dev/null || exit 0\n\nchanged=()\nwhile IFS= read -r -d '' file; do changed+=(\"$file\"); done < <(\n\tgit diff -z --name-only --relative --diff-filter=d HEAD 2>/dev/null\n\tgit ls-files -z --others --exclude-standard 2>/dev/null\n)\n((${#changed[@]})) || exit 0\n\nseen=\"$(git rev-parse --git-dir)/rogen-hook-$session\"\ntouch \"$seen\"\nreport=$(rogen check \"${changed[@]}\" | grep -vxF -f \"$seen\")\n[[ -z $report ]] && exit 0\nprintf '%s\\n' \"$report\" >>\"$seen\"\nmessage=$(printf 'Rogen warns about files you changed. Fix each, or tell the user why it stays:\\n%s' \"$report\")\nif [[ ${1:-} == cursor ]]; then\n\tjq -n --arg message \"$message\" '{followup_message: $message}'\nelse\n\tjq -n --arg message \"$message\" '{decision: \"block\", reason: $message}'\nfi\n";
